def solve_probability_inverse():
    count = 0
    # Total 5-digit numbers: 10000 to 99999
    total_numbers = 90000

    # Iterate through all possible digits
    # a1: 1-9, others: 0-9
    for a1 in range(1, 10):
        for a2 in range(10):
            for a3 in range(10):
                for a4 in range(10):
                    for a5 in range(10):
                        # Condition: a1 <= a2 + 1 <= a3 - 7 < a4 <= a5 + 2
                        if (a1 <= a2 + 1) and (a2 + 1 <= a3 - 7) and (a3 - 7 < a4) and (a4 <= a5 + 2):
                            count += 1

    a = count / total_numbers
    return round(1 / a) if a > 0 else None

def calculate_inverse_prob(total_range_start, total_range_end):
    count = 0
    total_numbers = total_range_end - total_range_start + 1
    for n in range(total_range_start, total_range_end + 1):
        s = str(n)
        a1, a2, a3, a4, a5 = map(int, s)
        if (a1 <= a2 + 1) and (a2 + 1 <= a3 - 7) and (a3 - 7 < a4) and (a4 <= a5 + 2):
            count += 1
    a = count / total_numbers
    return round(1 / a) if a > 0 else None

