def solve_min_products(fixed_cost, variable_cost, price):
    x = 1
    while True:
        revenue = x * price
        if x < 100:
            tax_rate = 0.10
        elif x < 300:
            tax_rate = 0.08
        else:
            tax_rate = 0.05

        tax = revenue * tax_rate
        total_cost = fixed_cost + (x * variable_cost)
        profit = revenue - tax - total_cost

        if profit > 0:
            return x
        x += 1

def maximize_profit(c_const, c_lin, c_quad, c_cub, p_const, p_lin):
    # Profit P(x) = Revenue R(x) - Cost C(x)
    # R(x) = x * p(x) = x * (p_const + p_lin * x) = p_const*x + p_lin*x^2
    # P(x) = (p_const*x + p_lin*x^2) - (c_const + c_lin*x + c_quad*x^2 + c_cub*x^3)
    # P(x) = -c_cub*x^3 + (p_lin - c_quad)*x^2 + (p_const - c_lin)*x - c_const
    # P'(x) = -3*c_cub*x^2 + 2*(p_lin - c_quad)*x + (p_const - c_lin)
    # Solve P'(x) = 0 using quadratic formula: ax^2 + bx + c = 0
    a = -3 * c_cub
    b = 2 * (p_lin - c_quad)
    c = p_const - c_lin

    discriminant = b**2 - 4*a*c
    if discriminant < 0:
        return None

    x1 = (-b + discriminant**0.5) / (2 * a)
    x2 = (-b - discriminant**0.5) / (2 * a)

    # P''(x) = -6*c_cub*x + 2*(p_lin - c_quad)
    # For maximum, P''(x) < 0
    def p_double_prime(x):
        return -6 * c_cub * x + 2 * (p_lin - c_quad)

    if p_double_prime(x1) < 0:
        return round(x1)
    elif p_double_prime(x2) < 0:
        return round(x2)
    return None

