def count_rotor_arrangements(n_slots=9, masses=None):
    if masses is None:
        masses = list(range(1, 10))

    total_mass = sum(masses)
    if total_mass % 3 != 0:
        return 0
    target = total_mass // 3

    # Find all subsets of 3 masses that sum to target
    valid_triplets = []
    for combo in itertools.combinations(masses, 3):
        if sum(combo) == target:
            valid_triplets.append(set(combo))

    # Find partitions of the 9 masses into 3 disjoint triplets
    partitions = []
    for i in range(len(valid_triplets)):
        for j in range(i + 1, len(valid_triplets)):
            for k in range(j + 1, len(valid_triplets)):
                s1, s2, s3 = valid_triplets[i], valid_triplets[j], valid_triplets[k]
                if s1.isdisjoint(s2) and s1.isdisjoint(s3) and s2.isdisjoint(s3):
                    partitions.append((s1, s2, s3))

    # For each partition, we assign the 3 groups to the 3 equilateral triangles
    # Triangle 1: {1, 4, 7}, Triangle 2: {2, 5, 8}, Triangle 3: {3, 6, 9}
    # There are 3! ways to assign groups to triangles
    # In each triangle, there are 3! ways to arrange the 3 blades
    count = 0
    for p in partitions:
        # 3! ways to assign the 3 sets to the 3 fixed triangle positions
        # and (3!)^3 ways to permute blades within those positions
        count += 6 * (6**3)

    return count

